formulas.expression:
BLANKVALUE(
    TRIM(
        IF(
            CONTAINS(TRIM({!NameAdmin}), " "),
            RIGHT(
                TRIM({!NameAdmin}),
                LEN(TRIM({!NameAdmin})) - FIND(" ", TRIM({!NameAdmin}))
            ),
            TRIM({!NameAdmin})
        )
    ),
    ""
)

BLANKVALUE(
    TRIM(
        IF(
            AND(
                CONTAINS(TRIM({!NameOthers}), " "),
                LEN(TRIM({!NameOthers})) > FIND(" ", TRIM({!NameOthers}))
            ),
            TRIM(
                RIGHT(
                    TRIM({!NameOthers}),
                    LEN(TRIM({!NameOthers})) - FIND(" ", TRIM({!NameOthers}))
                )
            ),
            TRIM({!NameOthers})
        )
    ),
    IF(
        NOT(ISBLANK(TRIM({!Company_NameOthers}))),
        TRIM({!Company_NameOthers}),
        "Contact"
    )
)

validationRule.formulaExpression:
IF(
{!DepartmentAdminCRMUser} <> null,
OR(
    AND(
        ISBLANK({!DepartmentAdminCRMUser}),
        ISBLANK({!Product_category_Repeater.AllItems[$EachItem].DepartmentNameAdmin2.topValue})
    ),
    AND(
        {!DepartmentAdminCRMUser} = {!Product_category_Repeater.AllItems[$EachItem].DepartmentNameAdmin2.topValue},
        NOT(ISBLANK({!Product_category_Repeater.AllItems[$EachItem].DepartmentNameAdmin2.middleValue}))
    )
),
OR(
    AND(
        ISBLANK({!DepartmentHODCRMHeadSales}),
        ISBLANK({!Product_category_Repeater.AllItems[$EachItem].DepartmentNameAdmin2.topValue})
    ),
    AND(
        {!DepartmentHODCRMHeadSales} = {!Product_category_Repeater.AllItems[$EachItem].DepartmentNameAdmin2.topValue},
        NOT(ISBLANK({!Product_category_Repeater.AllItems[$EachItem].DepartmentNameAdmin2.middleValue}))
    )
)
)
